    let req_002 = format!(
        r#"
id = "REQ-002"
version = 1
feat = "FEAT-Auth"
hash = "{other_hash}"
status = "active"
statement = "{other_statement}"
acceptance = [
    "{a0}",
]
"#,
        a0 = other_acceptance[0],
    );
    fs::write(auth_dir.join("REQ-002.toml"), req_002).expect("write REQ-002");

    dir
}

